settings.custom_liquid:
{{ 'component-upsell-products.css' | asset_url | stylesheet_tag }}
<div class="complete-the-look" id="ctl-{{ section.id }}" data-product-id="{{ product.id }}" data-url="{{ routes.product_recommendations_url }}.json" data-money="{{ shop.money_format | escape }}" hidden>
  <div class="rte mb-8"><h3>Complete the look</h3><p>Pair it with pieces picked to style perfectly together.</p></div>
  <div class="upsell-products grid grid-cols-1" style="--gap: 8px;"></div>
</div>
<script>
(function () {
  var root = document.getElementById('ctl-{{ section.id }}');
  if (!root || root.dataset.init) return;
  root.dataset.init = '1';
  var list = root.querySelector('.upsell-products');
  var moneyFormat = root.dataset.money;
  function money(cents) {
    var n = (cents / 100);
    var fmt = function (d, ts, ds) { var p = n.toFixed(d).split('.'); p[0] = p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ts); return p.join(ds); };
    return moneyFormat.replace(/\{\s*\{\s*(\w+)\s*\}\s*\}/, function (m, k) {
      if (k === 'amount_no_decimals') return fmt(0, ',', '.');
      if (k === 'amount_with_comma_separator') return fmt(2, '.', ',');
      if (k === 'amount_no_decimals_with_comma_separator') return fmt(0, '.', ',');
      return fmt(2, ',', '.');
    });
  }
  function esc(s) { var d = document.createElement('div'); d.textContent = s || ''; return d.innerHTML; }
  var basket = '<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="icon icon-shopping-basket"><path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"></path><line x1="3" y1="6" x2="21" y2="6"></line><path d="M16 10a4 4 0 0 1-8 0"></path></svg><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="icon icon-plus"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>';
  function card(p) {
    var v = p.variants[0];
    var img = p.featured_image ? p.featured_image + (p.featured_image.indexOf('?') > -1 ? '&' : '?') + 'width=180' : '';
    var onSale = p.compare_at_price && p.compare_at_price > p.price;
    var price = '<div class="price size--small mt-4' + (onSale ? ' price--on-sale' : '') + '"><div class="flex">' +
      (onSale ? '<s class="price-item price-item--regular style--subdued">' + money(p.compare_at_price) + '</s>&nbsp;&nbsp;' : '') +
      '<span class="price-item price-item--' + (onSale ? 'sale' : 'regular') + '">' + (p.price_varies ? 'From ' : '') + money(p.price) + '</span></div></div>';
    var single = p.variants.length === 1 && v.available;
    var formId = 'ctl-form-{{ section.id }}-' + p.id;
    var action = single
      ? '<button type="submit" name="add" class="btn btn--primary icon-btn--quick-buy for-submit" aria-label="Add ' + esc(p.title) + ' to cart"><span class="quick-buy-icon">' + basket + '</span><div class="loading-overlay hidden"><div class="loading-overlay__spinner"></div></div></button>'
      : '<a href="' + p.url + '" class="btn btn--primary icon-btn--quick-buy" aria-label="Choose options for ' + esc(p.title) + '"><span class="quick-buy-icon">' + basket + '</span></a>';
    return '<div class="card card--product card--product-upsell card--default layout--thumbnail">' +
      '<a href="' + p.url + '" class="card-media"><figure class="media square cover br-img"><img width="90" height="90" loading="lazy" src="' + img + '" alt="' + esc(p.title) + '"></figure></a>' +
      '<product-form class="product-form"><form method="post" action="{{ routes.cart_add_url }}" id="' + formId + '" class="form upsell-body" novalidate data-type="add-to-cart-form">' +
      '<input type="hidden" name="form_type" value="product"><input type="hidden" name="id" value="' + v.id + '"><input type="hidden" name="quantity" value="1">' +
      '<div class="product-form__error-message-wrapper" role="alert" hidden><span class="product-form__error-message"></span></div>' +
      '<div class="card-body"><h3 class="card-title font-body"><a href="' + p.url + '">' + esc(p.title) + '</a></h3>' + price + '</div>' +
      '<div class="card-actions">' + action + '</div></form></product-form></div>';
  }
  function load(intent) {
    return fetch(root.dataset.url + '?product_id=' + root.dataset.productId + '&limit=4&intent=' + intent)
      .then(function (r) { return r.ok ? r.json() : { products: [] }; })
      .then(function (d) { return (d.products || []).filter(function (p) { return p.available; }); });
  }
  load('complementary').then(function (items) {
    return items.length ? items : load('related');
  }).then(function (items) {
    if (!items.length) return;
    list.innerHTML = items.slice(0, 3).map(card).join('');
    root.hidden = false;
  }).catch(function () {});
})();
</script>
